// swift-tools-version:5.9
// NoelKit: noel-ffi's Swift bindings (generated by `make ios`) over the
// NoelFFI xcframework, and an SSH channel opener on Citadel.
import PackageDescription

let package = Package(
    name: "NoelKit",
    platforms: [.iOS(.v17), .macOS(.v14)],
    products: [.library(name: "NoelKit", targets: ["NoelKit"])],
    dependencies: [
        .package(url: "https://github.com/orlandos-nl/Citadel.git", from: "0.9.0"),
        .package(url: "https://github.com/apple/swift-nio.git", from: "2.65.0"),
    ],
    targets: [
        // Built by `make ios`: noel-ffi for aarch64-apple-ios and
        // aarch64-apple-ios-sim, with its header and module map.
        .binaryTarget(name: "NoelFFI", path: "build/NoelFFI.xcframework"),
        .target(
            name: "NoelKit",
            dependencies: [
                "NoelFFI",
                .product(name: "Citadel", package: "Citadel"),
                .product(name: "NIOCore", package: "swift-nio"),
                .product(name: "NIOFoundationCompat", package: "swift-nio"),
            ],
            path: "NoelKit/Sources/NoelKit"
        ),
    ]
)
